  box-shadow: 0 30px 80px rgba(0,0,0,0.5);
  font-size: 12px;
  display: none;
  flex-direction: column;
  gap: 14px;
}
.tweaks.is-visible { display: flex; }
.tweaks__header {
  display: flex;
  justify-content: space-between;
  align-items: center;
}
.tweaks__title {
  font-weight: 700;
  letter-spacing: -0.01em;
  font-size: 13px;
}
.tweaks__close {
  font-family: var(--font-family-mono);
  font-size: 10px;
  letter-spacing: 0.2em;
  color: var(--color-textSecondary);
}
.tweaks__row {
  display: flex;
  flex-direction: column;
  gap: 6px;
}
.tweaks__label {
  font-family: var(--font-family-mono);
  font-size: 10px;
  letter-spacing: 0.2em;
  text-transform: uppercase;
  color: var(--color-textSecondary);
  display: flex;
  justify-content: space-between;
}
.tweaks__swatches {
  display: flex;
  gap: 8px;
}
.tweaks__swatch {
  width: 28px; height: 28px;
  border-radius: 50%;
  cursor: pointer;
  border: 1.5px solid transparent;
  transition: border-color var(--dur-fast) var(--ghost-ease);
}
.tweaks__swatch.is-active { border-color: var(--color-text); }
.tweaks input[type="range"] {
  width: 100%;
  accent-color: var(--color-blueAccent);
}
.tweaks__toggle {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 6px 10px;
  border-radius: 8px;
  border: 1px solid var(--surface-border);
  background: transparent;
  color: var(--color-text);
  font-size: 11px;
  cursor: pointer;
}
.tweaks__toggle.is-active {
  border-color: var(--color-blueAccent);
  background: rgba(79, 230, 255, 0.1);
}

