## Best Practices

1. **Use `viewport={{ once: true }}`**: Prevents re-triggering on scroll back
2. **Add margin to viewport**: Trigger slightly before element is visible
3. **Use `useSpring` for progress**: Smoother progress bar animations
4. **Keep parallax subtle**: Small movements (50-100px) feel more natural
5. **Test performance**: Heavy scroll animations can impact mobile performance
6. **Consider reduced motion**: Disable parallax for `prefers-reduced-motion`

/**
 * Animated List Template
 *
 * A comprehensive animated list component with:
 * - Staggered entrance animations
 * - Smooth entry/exit for items
 * - Drag-to-reorder functionality
 * - Item removal animations
 *
 * Usage:
 * ```tsx
 * import { AnimatedList, AnimatedListItem } from "@/components/animated-list";
 *
 * function MyList() {
 *   const [items, setItems] = useState([...]);
 *
 *   return (
 *     <AnimatedList>
 *       {items.map((item) => (
 *         <AnimatedListItem key={item.id}>
 *           {item.content}
 *         </AnimatedListItem>
 *       ))}
 *     </AnimatedList>
 *   );
 * }
 * ```
 */

"use client";

import { ReactNode, useState } from "react";
import {
  AnimatePresence,
  motion,
  Reorder,
  useDragControls,
  Variants,
} from "framer-motion";
import { GripVertical, X } from "lucide-react";

// ============================================================================
// Animation Variants
// ============================================================================

const containerVariants: Variants = {
  hidden: { opacity: 0 },
  visible: {
    opacity: 1,
    transition: {
      staggerChildren: 0.08,
      delayChildren: 0.1,
    },
  },
};

const itemVariants: Variants = {
  hidden: {
    opacity: 0,
    y: 20,
    scale: 0.95,
  },
  visible: {
    opacity: 1,
    y: 0,
    scale: 1,
    transition: {
      type: "spring",
      stiffness: 300,
      damping: 24,
    },
  },
  exit: {
    opacity: 0,
    scale: 0.9,
    x: -20,
    transition: {
      duration: 0.2,
    },
  },
};

// ============================================================================
// Basic Animated List (No Reordering)
// ============================================================================

interface AnimatedListProps {
  children: ReactNode;
  className?: string;
}

/**
 * AnimatedList - Container with staggered children animation
 *
 * Use with AnimatedListItem for individual item animations.
 */
export function AnimatedList({ children, className }: AnimatedListProps) {
  return (
    <motion.ul
      variants={containerVariants}
      initial="hidden"
      animate="visible"
      className={className}
    >
      {children}
    </motion.ul>
  );
}

interface AnimatedListItemProps {
  children: ReactNode;
  className?: string;
  /**
   * Called when remove button is clicked
   */
  onRemove?: () => void;
  /**
   * Show remove button on hover
   * @default false
   */
  showRemove?: boolean;
}

/**
 * AnimatedListItem - Individual list item with animations
 *
 * Features:
 * - Enters with staggered spring animation
 * - Exit animation when removed
 * - Optional remove button on hover
 */
export function AnimatedListItem({
  children,
  className,
  onRemove,
  showRemove = false,
}: AnimatedListItemProps) {
  return (
    <motion.li
      layout
      variants={itemVariants}
      exit="exit"
      className={`group relative ${className || ""}`}
    >
      {children}
      {showRemove && onRemove && (
        <motion.button
          initial={{ opacity: 0, scale: 0.8 }}
          whileHover={{ scale: 1.1 }}
          whileTap={{ scale: 0.9 }}
          className="absolute right-2 top-1/2 -translate-y-1/2 opacity-0 group-hover:opacity-100 transition-opacity p-1 text-muted-foreground hover:text-destructive"
          onClick={onRemove}
        >
          <X className="h-4 w-4" />
        </motion.button>
      )}
    </motion.li>
  );
}

// ============================================================================
// Animated List with Entry/Exit (AnimatePresence)
// ============================================================================

interface DynamicListProps<T> {
  items: T[];
  keyExtractor: (item: T) => string;
  renderItem: (item: T, index: number) => ReactNode;
  className?: string;
}

/**
 * DynamicList - List with smooth add/remove animations
 *
 * Wraps items in AnimatePresence for exit animations.
 *
 * @example
 * ```tsx
 * <DynamicList
 *   items={todos}
 *   keyExtractor={(todo) => todo.id}
 *   renderItem={(todo) => <TodoItem todo={todo} />}
 * />
 * ```
 */
export function DynamicList<T>({
  items,
  keyExtractor,
  renderItem,
  className,
}: DynamicListProps<T>) {
  return (
    <motion.ul layout className={className}>
      <AnimatePresence mode="popLayout">
        {items.map((item, index) => (
          <motion.li
            key={keyExtractor(item)}
            layout
            initial={{ opacity: 0, scale: 0.8, y: -10 }}
            animate={{ opacity: 1, scale: 1, y: 0 }}
            exit={{ opacity: 0, scale: 0.8, x: -50 }}
            transition={{
              type: "spring",
              stiffness: 300,
              damping: 24,
            }}
          >
            {renderItem(item, index)}
          </motion.li>
        ))}
      </AnimatePresence>
    </motion.ul>
  );
}

// ============================================================================
// Reorderable List (Drag to Reorder)
// ============================================================================

interface ReorderableListProps<T> {
  items: T[];
  onReorder: (items: T[]) => void;
  keyExtractor: (item: T) => string;
  renderItem: (item: T, dragControls: ReturnType<typeof useDragControls>) => ReactNode;
  className?: string;
  /**
   * Axis for reordering
   * @default "y"
   */
  axis?: "x" | "y";
}

/**
 * ReorderableList - Drag-to-reorder list
 *
 * Uses Framer Motion's Reorder component for smooth reordering.
 *
 * @example
 * ```tsx
 * const [items, setItems] = useState(initialItems);
 *
 * <ReorderableList
 *   items={items}
 *   onReorder={setItems}
 *   keyExtractor={(item) => item.id}
 *   renderItem={(item, dragControls) => (
 *     <ReorderableItem item={item} dragControls={dragControls} />
 *   )}
 * />
 * ```
 */
export function ReorderableList<T>({
  items,
  onReorder,
  keyExtractor,
  renderItem,
  className,
  axis = "y",
}: ReorderableListProps<T>) {
  return (
    <Reorder.Group
      axis={axis}
      values={items}
      onReorder={onReorder}
      className={className}
    >
      {items.map((item) => (
        <ReorderableItemWrapper
          key={keyExtractor(item)}
          item={item}
          renderItem={renderItem}
        />
      ))}
    </Reorder.Group>
  );
}

// Internal wrapper to provide drag controls
function ReorderableItemWrapper<T>({
  item,
  renderItem,
}: {
  item: T;
  renderItem: (item: T, dragControls: ReturnType<typeof useDragControls>) => ReactNode;
}) {
  const dragControls = useDragControls();

  return (
    <Reorder.Item
      value={item}
      dragControls={dragControls}
      dragListener={false}
    >
      {renderItem(item, dragControls)}
    </Reorder.Item>
  );
}

// ============================================================================
// Drag Handle Component
// ============================================================================

interface DragHandleProps {
  dragControls: ReturnType<typeof useDragControls>;
  className?: string;
}

/**
 * DragHandle - Grab handle for reorderable items
 *
 * @example
 * ```tsx
 * renderItem={(item, dragControls) => (
 *   <div className="flex items-center gap-2">
 *     <DragHandle dragControls={dragControls} />
 *     <span>{item.name}</span>
 *   </div>
 * )}
 * ```
 */
export function DragHandle({ dragControls, className }: DragHandleProps) {
  return (
    <div
      onPointerDown={(e) => dragControls.start(e)}
      className={`cursor-grab active:cursor-grabbing touch-none ${className || ""}`}
    >
      <GripVertical className="h-5 w-5 text-muted-foreground" />
    </div>
  );
}

// ============================================================================
// Complete Reorderable Todo List Example
// ============================================================================

interface TodoItem {
  id: string;
  text: string;
  completed: boolean;
}

interface ReorderableTodoListProps {
  initialItems?: TodoItem[];
}

/**
 * ReorderableTodoList - Complete example of an animated, reorderable todo list
 *
 * Features:
 * - Drag to reorder
 * - Add new items
 * - Remove items with animation
 * - Toggle completion state
 */
export function ReorderableTodoList({
  initialItems = [],
}: ReorderableTodoListProps) {
  const [items, setItems] = useState<TodoItem[]>(initialItems);
  const [newItemText, setNewItemText] = useState("");

  function addItem() {
    if (!newItemText.trim()) return;
    setItems([
      ...items,
      {
        id: crypto.randomUUID(),
        text: newItemText.trim(),
        completed: false,
      },
    ]);
    setNewItemText("");
  }

  function removeItem(id: string) {
    setItems(items.filter((item) => item.id !== id));
  }

  function toggleItem(id: string) {
    setItems(
      items.map((item) =>
        item.id === id ? { ...item, completed: !item.completed } : item
      )
    );
  }

  return (
    <div className="space-y-4">
      {/* Add item form */}
      <div className="flex gap-2">
        <input
          type="text"
          value={newItemText}
          onChange={(e) => setNewItemText(e.target.value)}
          onKeyDown={(e) => e.key === "Enter" && addItem()}
          placeholder="Add new item..."
          className="flex-1 px-3 py-2 border rounded-lg focus:ring-2 focus:ring-primary outline-none"
        />
        <motion.button
          whileHover={{ scale: 1.05 }}
          whileTap={{ scale: 0.95 }}
          onClick={addItem}
          className="px-4 py-2 bg-primary text-primary-foreground rounded-lg"
        >
          Add
        </motion.button>
      </div>

      {/* Reorderable list */}
      <Reorder.Group
        axis="y"
        values={items}
        onReorder={setItems}
        className="space-y-2"
      >
        <AnimatePresence mode="popLayout">
          {items.map((item) => (
            <TodoListItem
              key={item.id}
              item={item}
              onToggle={() => toggleItem(item.id)}
              onRemove={() => removeItem(item.id)}
            />
          ))}
        </AnimatePresence>
      </Reorder.Group>

      {/* Empty state */}
      {items.length === 0 && (
        <motion.p
          initial={{ opacity: 0 }}
          animate={{ opacity: 1 }}
          className="text-center text-muted-foreground py-8"
        >
          No items yet. Add one above!
        </motion.p>
      )}
    </div>
  );
}

// Internal todo item component
function TodoListItem({
  item,
  onToggle,
  onRemove,
}: {
  item: TodoItem;
  onToggle: () => void;
  onRemove: () => void;
}) {
  const dragControls = useDragControls();

  return (
    <Reorder.Item
      value={item}
      dragControls={dragControls}
      dragListener={false}
      initial={{ opacity: 0, y: -10 }}
      animate={{ opacity: 1, y: 0 }}
      exit={{ opacity: 0, scale: 0.9, x: -50 }}
      transition={{ type: "spring", stiffness: 300, damping: 24 }}
      className="flex items-center gap-3 p-4 bg-card rounded-lg border"
    >
      {/* Drag handle */}
      <div
        onPointerDown={(e) => dragControls.start(e)}
        className="cursor-grab active:cursor-grabbing touch-none"
      >
        <GripVertical className="h-5 w-5 text-muted-foreground" />
      </div>

      {/* Checkbox */}
      <motion.input
        type="checkbox"
        checked={item.completed}
        onChange={onToggle}
        whileTap={{ scale: 0.9 }}
        className="h-4 w-4"
      />

      {/* Text */}
      <motion.span
        animate={{
          opacity: item.completed ? 0.5 : 1,
          textDecoration: item.completed ? "line-through" : "none",
        }}
        className="flex-1"
      >
        {item.text}
      </motion.span>

      {/* Remove button */}
      <motion.button
        whileHover={{ scale: 1.1 }}
        whileTap={{ scale: 0.9 }}
        onClick={onRemove}
        className="p-1 text-muted-foreground hover:text-destructive"
      >
        <X className="h-4 w-4" />
      </motion.button>
    </Reorder.Item>
  );
}

/**
 * Page Transition Template
 *
 * A reusable page transition wrapper for Next.js App Router.
 * Provides smooth enter/exit animations between routes.
 *
 * Usage:
 * 1. Use in individual pages:
 *    ```tsx
 *    // app/about/page.tsx
 *    import { PageTransition } from "@/components/page-transition";
 *
 *    export default function AboutPage() {
 *      return (
 *        <PageTransition>
 *          <h1>About</h1>
 *          <p>Page content...</p>
 *        </PageTransition>
 *      );
 *    }
 *    ```
 *
 * 2. Or use in template.tsx for app-wide transitions:
 *    ```tsx
 *    // app/template.tsx
 *    import { PageTransitionProvider } from "@/components/page-transition";
 *
 *    export default function Template({ children }: { children: React.ReactNode }) {
 *      return <PageTransitionProvider>{children}</PageTransitionProvider>;
 *    }
 *    ```
 */

"use client";

import { ReactNode } from "react";
import { AnimatePresence, motion, Variants } from "framer-motion";
import { usePathname } from "next/navigation";

// ============================================================================
// Transition Variants - Choose or customize
// ============================================================================

/**
 * Fade transition - Simple opacity change
 */
export const fadeVariants: Variants = {
  initial: {
    opacity: 0,
  },
  enter: {
    opacity: 1,
    transition: {
      duration: 0.3,
      ease: "easeOut",
    },
  },
  exit: {
    opacity: 0,
    transition: {
      duration: 0.2,
      ease: "easeIn",
    },
  },
};

/**
 * Slide up transition - Content slides up while fading
 */
export const slideUpVariants: Variants = {
  initial: {
    opacity: 0,
    y: 20,
  },
  enter: {
    opacity: 1,
    y: 0,
    transition: {
      duration: 0.4,
      ease: [0.25, 0.1, 0.25, 1],
    },
  },
  exit: {
    opacity: 0,
    y: -20,
    transition: {
      duration: 0.3,
      ease: [0.25, 0.1, 0.25, 1],
    },
  },
};

/**
 * Scale transition - Content scales while fading
 */
export const scaleVariants: Variants = {
  initial: {
    opacity: 0,
    scale: 0.98,
  },
  enter: {
    opacity: 1,
    scale: 1,
    transition: {
      duration: 0.4,
      ease: [0.25, 0.1, 0.25, 1],
    },
  },
  exit: {
    opacity: 0,
    scale: 0.98,
    transition: {
      duration: 0.3,
    },
  },
};

/**
 * Slide with scale - Combined slide and scale effect
 */
export const slideScaleVariants: Variants = {
  initial: {
    opacity: 0,
    y: 30,
    scale: 0.98,
  },
  enter: {
    opacity: 1,
    y: 0,
    scale: 1,
    transition: {
      duration: 0.5,
      ease: [0.25, 0.1, 0.25, 1],
    },
  },
  exit: {
    opacity: 0,
    y: -20,
    scale: 0.98,
    transition: {
      duration: 0.3,
    },
  },
};

// ============================================================================
// Page Transition Component
// ============================================================================

interface PageTransitionProps {
  children: ReactNode;
  /**
   * Choose a preset variant or provide custom variants
   * @default "slideUp"
   */
  variant?: "fade" | "slideUp" | "scale" | "slideScale" | Variants;
  /**
   * Additional CSS classes for the motion wrapper
   */
  className?: string;
}

const variantMap = {
  fade: fadeVariants,
  slideUp: slideUpVariants,
  scale: scaleVariants,
  slideScale: slideScaleVariants,
};

/**
 * PageTransition - Wrap your page content for enter animations
 *
 * Note: This only animates enter. For exit animations with route changes,
 * use PageTransitionProvider in template.tsx
 */
export function PageTransition({
  children,
  variant = "slideUp",
  className,
}: PageTransitionProps) {
  const variants = typeof variant === "string" ? variantMap[variant] : variant;

  return (
    <motion.div
      variants={variants}
      initial="initial"
      animate="enter"
      exit="exit"
      className={className}
    >
      {children}
    </motion.div>
  );
}

// ============================================================================
// Page Transition Provider (for template.tsx)
// ============================================================================

interface PageTransitionProviderProps {
  children: ReactNode;
  /**
   * Choose a preset variant or provide custom variants
   * @default "slideUp"
   */
  variant?: "fade" | "slideUp" | "scale" | "slideScale" | Variants;
  /**
   * AnimatePresence mode
   * - "wait": Wait for exit before enter (recommended)
   * - "sync": Enter and exit simultaneously
   * - "popLayout": Maintain layout during exit
   * @default "wait"
   */
  mode?: "wait" | "sync" | "popLayout";
  /**
   * Additional CSS classes for the motion wrapper
   */
  className?: string;
}

/**
 * PageTransitionProvider - Use in template.tsx for app-wide transitions
 *
 * Provides AnimatePresence wrapper that enables exit animations
 * when navigating between routes.
 */
export function PageTransitionProvider({
  children,
  variant = "slideUp",
  mode = "wait",
  className,
}: PageTransitionProviderProps) {
  const pathname = usePathname();
  const variants = typeof variant === "string" ? variantMap[variant] : variant;

  return (
    <AnimatePresence mode={mode}>
      <motion.div
        key={pathname}
        variants={variants}
        initial="initial"
        animate="enter"
        exit="exit"
        className={className}
      >
        {children}
      </motion.div>
    </AnimatePresence>
  );
}

// ============================================================================
// Staggered Page Content
// ============================================================================

const staggerContainerVariants: Variants = {
  initial: {
    opacity: 0,
  },
  enter: {
    opacity: 1,
    transition: {
      duration: 0.3,
      when: "beforeChildren",
      staggerChildren: 0.1,
    },
  },
  exit: {
    opacity: 0,
    transition: {
      duration: 0.2,
    },
  },
};

const staggerItemVariants: Variants = {
  initial: {
    opacity: 0,
    y: 20,
  },
  enter: {
    opacity: 1,
    y: 0,
    transition: {
      duration: 0.4,
      ease: [0.25, 0.1, 0.25, 1],
    },
  },
};

interface StaggeredPageProps {
  children: ReactNode;
  className?: string;
}

/**
 * StaggeredPage - Page wrapper that staggers child animations
 *
 * Use motion.div with variants={staggerItemVariants} for children
 * to get staggered entrance effect.
 *
 * @example
 * ```tsx
 * <StaggeredPage>
 *   <motion.h1 variants={staggerItemVariants}>Title</motion.h1>
 *   <motion.p variants={staggerItemVariants}>Content</motion.p>
 *   <motion.div variants={staggerItemVariants}>More content</motion.div>
 * </StaggeredPage>
 * ```
 */
export function StaggeredPage({ children, className }: StaggeredPageProps) {
  return (
    <motion.div
      variants={staggerContainerVariants}
      initial="initial"
      animate="enter"
      exit="exit"
      className={className}
    >
      {children}
    </motion.div>
  );
}

// Export the item variants for use in children
export { staggerItemVariants };

# Gestures Reference

Framer Motion provides gesture recognition for hover, tap, pan, and drag.

## Hover Gestures

### Basic Hover

```tsx
<motion.div
  whileHover={{ scale: 1.1 }}
  onHoverStart={() => console.log("Hover started")}
  onHoverEnd={() => console.log("Hover ended")}
>
  Hover me
</motion.div>
```

### Hover with Transition

```tsx
<motion.button
  whileHover={{
    scale: 1.05,
    backgroundColor: "#3b82f6",
    color: "#ffffff",
  }}
  transition={{ duration: 0.2 }}
>
  Hover Button
</motion.button>
```

### Hover Card Effect

```tsx
<motion.div
  whileHover={{
    y: -5,
    boxShadow: "0 20px 25px -5px rgba(0, 0, 0, 0.1)",
  }}
  transition={{ type: "spring", stiffness: 300 }}
  className="p-6 rounded-lg border"
>
  Card content
</motion.div>
```

## Tap Gestures

### Basic Tap

```tsx
<motion.button
  whileTap={{ scale: 0.95 }}
  onTap={() => console.log("Tapped!")}
>
  Click me
</motion.button>
```

### Tap Events

```tsx
<motion.button
  whileTap={{ scale: 0.95 }}
  onTapStart={(event, info) => {
    console.log("Tap started at", info.point);
  }}
  onTap={(event, info) => {
    console.log("Tap completed at", info.point);
  }}
  onTapCancel={() => {
    console.log("Tap cancelled");
  }}
>
  Button
</motion.button>
```

### Combined Hover + Tap

```tsx
<motion.button
  whileHover={{ scale: 1.05 }}
  whileTap={{ scale: 0.95 }}
  transition={{ type: "spring", stiffness: 400, damping: 17 }}
>
  Interactive Button
</motion.button>
```

## Focus Gestures

```tsx
<motion.input
  whileFocus={{
    scale: 1.02,
    borderColor: "#3b82f6",
    boxShadow: "0 0 0 2px rgba(59, 130, 246, 0.5)",
  }}
  className="px-4 py-2 border rounded"
/>
```

## Pan Gestures

Pan recognizes movement without dragging.

```tsx
<motion.div
  onPan={(event, info) => {
    console.log("Delta:", info.delta.x, info.delta.y);
    console.log("Offset:", info.offset.x, info.offset.y);
    console.log("Point:", info.point.x, info.point.y);
    console.log("Velocity:", info.velocity.x, info.velocity.y);
  }}
  onPanStart={(event, info) => console.log("Pan started")}
  onPanEnd={(event, info) => console.log("Pan ended")}
>
  Pan me
</motion.div>
```

### Swipe Detection

```tsx
function SwipeCard({ onSwipe }) {
  return (
    <motion.div
      onPanEnd={(event, info) => {
        const threshold = 100;
        const velocity = 500;

        if (info.offset.x > threshold || info.velocity.x > velocity) {
          onSwipe("right");
        } else if (info.offset.x < -threshold || info.velocity.x < -velocity) {
          onSwipe("left");
        }
      }}
    >
      Swipe me
    </motion.div>
  );
}
```

## Drag Gestures

### Basic Drag

```tsx
<motion.div drag>
  Drag me anywhere
</motion.div>

// Constrained to axis
<motion.div drag="x">Horizontal only</motion.div>
<motion.div drag="y">Vertical only</motion.div>
```

### Drag Constraints

```tsx
// Pixel constraints
<motion.div
  drag
  dragConstraints={{
    top: -100,
    left: -100,
    right: 100,
    bottom: 100,
  }}
>
  Constrained drag
</motion.div>

// Reference element
const constraintsRef = useRef(null);

<div ref={constraintsRef} className="w-96 h-96 border">
  <motion.div
    drag
    dragConstraints={constraintsRef}
    className="w-20 h-20 bg-blue-500 rounded"
  />
</div>
```

### Drag Elasticity

```tsx
<motion.div
  drag
  dragConstraints={{ left: 0, right: 0, top: 0, bottom: 0 }}
  dragElastic={0.2}  // 0 = no elasticity, 1 = full elasticity
>
  Elastic drag
</motion.div>
```

### Drag Momentum

```tsx
<motion.div
  drag
  dragMomentum={true}  // Enable momentum (default)
  dragTransition={{ bounceStiffness: 600, bounceDamping: 20 }}
>
  Momentum drag
</motion.div>
```

### Drag Snap to Origin

```tsx
<motion.div drag dragSnapToOrigin>
  Snaps back when released
</motion.div>
```

### Drag Events

```tsx
<motion.div
  drag
  onDragStart={(event, info) => {
    console.log("Drag started at", info.point);
  }}
  onDrag={(event, info) => {
    console.log("Dragging:", info.point, info.delta, info.offset, info.velocity);
  }}
  onDragEnd={(event, info) => {
    console.log("Drag ended at", info.point);
    console.log("Velocity:", info.velocity);
  }}
>
  Drag me
</motion.div>
```

### Drag Direction Lock

```tsx
<motion.div
  drag
  dragDirectionLock
  onDirectionLock={(axis) => console.log(`Locked to ${axis}`)}
>
  Locks to first detected direction
</motion.div>
```

### Drag Controls

```tsx
import { motion, useDragControls } from "framer-motion";

function DraggableCard() {
  const dragControls = useDragControls();

  return (
    <>
      {/* Handle to initiate drag */}
      <div
        onPointerDown={(e) => dragControls.start(e)}
        className="cursor-grab"
      >
        Drag handle
      </div>

      <motion.div drag dragControls={dragControls} dragListener={false}>
        Draggable content (only via handle)
      </motion.div>
    </>
  );
}
```

### While Dragging Animation

```tsx
<motion.div
  drag
  whileDrag={{
    scale: 1.1,
    cursor: "grabbing",
    boxShadow: "0 10px 30px rgba(0,0,0,0.2)",
  }}
  className="cursor-grab"
>
  Drag me
</motion.div>
```

## Sortable List (Reorder)

```tsx
import { Reorder } from "framer-motion";

function SortableList() {
  const [items, setItems] = useState([1, 2, 3, 4]);

  return (
    <Reorder.Group
      axis="y"
      values={items}
