# Variants Reference

Variants are predefined animation states that simplify complex animations.

## Basic Variants

```tsx
const variants = {
  hidden: { opacity: 0 },
  visible: { opacity: 1 },
};

<motion.div
  variants={variants}
  initial="hidden"
  animate="visible"
>
  Fades in
</motion.div>
```

## Multiple Properties

```tsx
const variants = {
  hidden: {
    opacity: 0,
    y: 20,
    scale: 0.95,
  },
  visible: {
    opacity: 1,
    y: 0,
    scale: 1,
  },
};

<motion.div variants={variants} initial="hidden" animate="visible">
  Fades in, slides up, and scales
</motion.div>
```

## Transitions in Variants

```tsx
const variants = {
  hidden: {
    opacity: 0,
    y: 20,
  },
  visible: {
    opacity: 1,
    y: 0,
    transition: {
      duration: 0.5,
      ease: "easeOut",
    },
  },
  exit: {
    opacity: 0,
    y: -20,
    transition: {
      duration: 0.3,
    },
  },
};
```

## Parent-Child Orchestration

Children automatically inherit variants from parents:

```tsx
const container = {
  hidden: { opacity: 0 },
  visible: {
    opacity: 1,
    transition: {
      when: "beforeChildren",  // Animate parent first
      staggerChildren: 0.1,    // Delay between children
      delayChildren: 0.3,      // Delay before first child
    },
  },
};

const item = {
  hidden: { opacity: 0, y: 20 },
  visible: { opacity: 1, y: 0 },
};

<motion.ul variants={container} initial="hidden" animate="visible">
  <motion.li variants={item}>Item 1</motion.li>
  <motion.li variants={item}>Item 2</motion.li>
  <motion.li variants={item}>Item 3</motion.li>
</motion.ul>
```

## Stagger Options

```tsx
const container = {
  hidden: { opacity: 0 },
  visible: {
    opacity: 1,
    transition: {
      staggerChildren: 0.1,
      staggerDirection: 1,  // 1 = forward, -1 = reverse
      delayChildren: 0.2,
    },
  },
  exit: {
    opacity: 0,
    transition: {
      staggerChildren: 0.05,
      staggerDirection: -1,  // Reverse stagger on exit
      when: "afterChildren", // Wait for children to exit
    },
  },
};
```

## When Property

```tsx
const variants = {
  visible: {
    opacity: 1,
    transition: {
      when: "beforeChildren",  // Parent animates first
      // or
      when: "afterChildren",   // Children animate first
    },
  },
};
```

## Dynamic Variants

Pass custom values to variants:

```tsx
const variants = {
  hidden: { opacity: 0 },
  visible: (custom: number) => ({
    opacity: 1,
    transition: { delay: custom * 0.1 },
  }),
};

<motion.ul initial="hidden" animate="visible">
  {items.map((item, i) => (
    <motion.li
      key={item.id}
      variants={variants}
      custom={i}  // Pass index to variant
    >
      {item.name}
    </motion.li>
  ))}
</motion.ul>
```

